(function(){const T=window.VB_TRANSITIONS,D=window.VB_DATA;D.transitions=D.transitions.map(item=>({...item,...T.items[item.id],manualRevision:T.items[item.id].manualRevision||T.revision,legacyScores:[],scoring:{en:T.items[item.id].guidance.map(g=>g.label.en+": "+g.text.en).join("\n"),ar:T.items[item.id].guidance.map(g=>g.label.ar+": "+g.text.ar).join("\n")}}));})();

(function(){for(const item of window.VB_DATA.transitions){if(item.id==='tr-1'||item.id==='tr-2'){item.derivedFrom=item.id==='tr-1'?'milestones':'barriers';item.derivedItems=item.derivedFrom==='milestones'?window.VB_DATA.milestones.concat(window.VB_DATA.additionalMilestones||[]):window.VB_DATA.barriers;}}})();
